import{_ as t,c as o,o as r,ah as a}from"./chunks/framework.PvdZnrZd.js";const h=JSON.parse('{"title":"PRODUCT EXPIRY","description":"PRODUCT EXPIRY","frontmatter":{"title":"PRODUCT EXPIRY","description":"PRODUCT EXPIRY","date":"2025-08-07T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/marketplace-product-add-ons/product-expiry.md","filePath":"zenith/featured-app/marketplace-product-add-ons/product-expiry.md"}'),p={name:"zenith/featured-app/marketplace-product-add-ons/product-expiry.md"};function n(l,e,c,d,i,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<p><a href="/zenith/introduction/">Multivendor Marketplace app for Shopify</a>- Product Expiry App:- We have introduced a new feature in our Multivendor Marketplace app for Shopify name &quot;Expiry App&quot;</p><p>Which enables both admins as well as sellers to set an expiry date for the product while adding any new product or editing the existing product.</p><p>Once you will set the expiry date for any product, the product will automatically become unavailable on that set date.</p><p>This feature cost is USD 5 per month over and above your current multivendor marketplace plan.</p><p>So let&#39;s understand its workflow:-</p><h2 id="workflow" tabindex="-1">WORKFLOW <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;WORKFLOW&quot;">​</a></h2><p>Firstly you need to enable the &quot;Expiry App&quot; feature from the &#39;Feature Apps&#39; section by click on the (...) three dots of the main menu in the app.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexa.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexa.webp" alt="Multivendor Marketplace Product Expiry App"></a></p><p>Once you will click on Enable button you need to agree on additional charges USD 5 per month which is over and above your current Multivendor marketplace plan.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexb.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexb.webp" alt="Multivendor Marketplace Product Expiry App"></a></p><p>Now you will be able to add the expiry date for new products as well as for existing products</p><h2 id="for-new-product" tabindex="-1"><strong>FOR NEW PRODUCT:-</strong> <a class="header-anchor" href="#for-new-product" aria-label="Permalink to &quot;**FOR NEW PRODUCT:-**&quot;">​</a></h2><p>Configuration-&gt; Product -&gt; Product Listing -&gt; Add product-&gt; Enter expiry Date-&gt; fill the rest details-&gt; save</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexc.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexc.webp" alt="image"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexd.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexd.webp" alt="Multivendor Marketplace Product Expiry App"></a></p><h2 id="for-existing-product" tabindex="-1"><strong>FOR EXISTING PRODUCT:-</strong> <a class="header-anchor" href="#for-existing-product" aria-label="Permalink to &quot;**FOR EXISTING PRODUCT:-**&quot;">​</a></h2><p>Configuration-&gt; Products -&gt; Products listing -&gt; Click on &quot;Edit button&quot; of &quot;Action&quot; section in front of Product ID -&gt; Product details page will open -&gt; Enter the expiry date-&gt; Save</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexe.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexe.webp" alt="image"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexf.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/productexf.webp" alt="Multivendor Marketplace Product Expiry App"></a></p><h3 id="demo" tabindex="-1">DEMO <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;DEMO&quot;">​</a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',21)])])}const b=t(p,[["render",n]]);export{h as __pageData,b as default};
